3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"strconv"
12	)
13	
14	type pullRequest struct {
15		id     int
16		deps   []int
17		checks string
18	}
19	
20	type queueResult struct {
21		Waves   [][]int `json:"waves"`
22		Blocked []int   `json:"blocked"`
23	}
24	
25	func main() {
26		os.Exit(runCLI(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
27	}
28	
29	func runCLI(args []string, in io.Reader, out io.Writer, errOut io.Writer) int {
30		parallel, err := parseParallelArgs(args)
31		if err != nil {
32			_, _ = fmt.Fprintln(errOut, err)
33			return 2
34		}
35		return runWithParallel(in, out, errOut, parallel)
36	}
37	
38	func run(in io.Reader, out io.Writer, errOut io.Writer) int {
39		return runWithParallel(in, out, errOut, 0)
40	}
41	
42	func runWithParallel(in io.Reader, out io.Writer, errOut io.Writer, parallel int) int {
43		result, err := planWithParallel(in, parallel)
44		if err != nil {
45			_, _ = fmt.Fprintln(errOut, err)
46			return 2
47		}
48	
49		if err := json.NewEncoder(out).Encode(result); err != nil {
50			_, _ = fmt.Fprintln(errOut, "writing result: "+err.Error())
51			return 1
52		}
53		return 0
54	}
55	
56	func parseParallelArgs(args []string) (int, error) {
57		if len(args) == 0 {
58			return 0, nil
59		}
60		if len(args) != 2 || args[0] != "--parallel" {
61			return 0, errors.New("usage: mergequeue [--parallel N]")
62		}
63		parallel, err := strconv.Atoi(args[1])
64		if err != nil || parallel <= 0 {
65			return 0, fmt.Errorf("invalid --parallel value %q: N must be a positive integer", args[1])
66		}
67		return parallel, nil
68	}
