70	func plan(in io.Reader) (queueResult, error) {
71		return planWithParallel(in, 0)
72	}
73	
74	func planWithParallel(in io.Reader, parallel int) (queueResult, error) {
75		prs, err := decodeQueue(in)
76		if err != nil {
77			return queueResult{}, err
78		}
79	
80		byID := make(map[int]pullRequest, len(prs))
81		for _, pr := range prs {
82			if pr.id <= 0 {
83				return queueResult{}, fmt.Errorf("invalid PR id %d: IDs must be positive", pr.id)
84			}
85			if _, exists := byID[pr.id]; exists {
86				return queueResult{}, fmt.Errorf("duplicate PR id %d", pr.id)
87			}
88			if pr.checks != "pass" && pr.checks != "fail" && pr.checks != "pending" {
89				return queueResult{}, fmt.Errorf("PR %d has invalid checks status %q", pr.id, pr.checks)
90			}
91			byID[pr.id] = pr
92		}
93	
94		for _, pr := range prs {
95			for _, dep := range pr.deps {
96				if _, exists := byID[dep]; !exists {
97					return queueResult{}, fmt.Errorf("PR %d depends on missing PR %d", pr.id, dep)
98				}
99			}
100		}
101	
102		if cycleID, ok := findCycle(byID); ok {
103			return queueResult{}, fmt.Errorf("dependency cycle detected involving PR %d", cycleID)
104		}
105	
106		blocked := make(map[int]bool, len(byID))
107		var isBlocked func(int) bool
108		isBlocked = func(id int) bool {
109			if known, ok := blocked[id]; ok {
110				return known
111			}
112			pr := byID[id]
113			blocked[id] = pr.checks != "pass"
114			if !blocked[id] {
115				for _, dep := range pr.deps {
116					if isBlocked(dep) {
117						blocked[id] = true
118						break
119					}
120				}
121			}
122			return blocked[id]
123		}
124	
125		ids := sortedIDs(byID)
126		blockedIDs := make([]int, 0)
127		for _, id := range ids {
128			if isBlocked(id) {
129				blockedIDs = append(blockedIDs, id)
130			}
131		}
132	
133		scheduled := make(map[int]bool, len(byID))
134		waves := make([][]int, 0)
135		for {
136			wave := make([]int, 0)
137			for _, id := range ids {
138				if blocked[id] || scheduled[id] {
139					continue
140				}
141				ready := true
142				for _, dep := range byID[id].deps {
143					if !scheduled[dep] {
144						ready = false
145						break
146					}
147				}
148				if ready {
149					wave = append(wave, id)
150				}
151			}
152			if len(wave) == 0 {
153				break
154			}
155			if parallel > 0 && len(wave) > parallel {
156				wave = wave[:parallel]
157			}
158			for _, id := range wave {
159				scheduled[id] = true
160			}
161			waves = append(waves, wave)
162		}
163	
164		return queueResult{Waves: waves, Blocked: blockedIDs}, nil
165	}
