167	func decodeQueue(in io.Reader) ([]pullRequest, error) {
168		decoder := json.NewDecoder(in)
169		var raw json.RawMessage
170		if err := decoder.Decode(&raw); err != nil {
171			return nil, fmt.Errorf("invalid JSON input: %w", err)
172		}
173		if first := bytes.TrimSpace(raw); len(first) == 0 || first[0] != '{' {
174			return nil, errors.New("invalid input: top-level value must be a JSON object")
175		}
176	
177		var fields map[string]json.RawMessage
178		if err := json.Unmarshal(raw, &fields); err != nil {
179			return nil, fmt.Errorf("invalid JSON object: %w", err)
180		}
181		prsRaw, ok := fields["prs"]
182		if !ok {
183			return nil, errors.New("invalid input: missing prs array")
184		}
185		if first := bytes.TrimSpace(prsRaw); len(first) == 0 || first[0] != '[' {
186			return nil, errors.New("invalid input: prs must be an array")
187		}
188	
189		var rawPRs []json.RawMessage
190		if err := json.Unmarshal(prsRaw, &rawPRs); err != nil {
191			return nil, fmt.Errorf("invalid prs array: %w", err)
192		}
193		prs := make([]pullRequest, 0, len(rawPRs))
194		for index, rawPR := range rawPRs {
195			pr, err := decodePR(rawPR)
196			if err != nil {
197				return nil, fmt.Errorf("invalid PR at index %d: %w", index, err)
198			}
199			prs = append(prs, pr)
200		}
201	
202		var extra json.RawMessage
203		if err := decoder.Decode(&extra); err != io.EOF {
204			if err == nil {
205				return nil, errors.New("invalid input: extra JSON value after queue")
206			}
207			return nil, fmt.Errorf("invalid input after queue: %w", err)
208		}
209		return prs, nil
210	}
