212	func decodePR(raw json.RawMessage) (pullRequest, error) {
213		var fields map[string]json.RawMessage
214		if first := bytes.TrimSpace(raw); len(first) == 0 || first[0] != '{' {
215			return pullRequest{}, errors.New("PR must be a JSON object")
216		}
217		if err := json.Unmarshal(raw, &fields); err != nil {
218			return pullRequest{}, fmt.Errorf("PR must be a JSON object: %w", err)
219		}
220	
221		idRaw, ok := fields["id"]
222		if !ok {
223			return pullRequest{}, errors.New("missing id")
224		}
225		var id int
226		if err := json.Unmarshal(idRaw, &id); err != nil {
227			return pullRequest{}, fmt.Errorf("id must be an integer: %w", err)
228		}
229	
230		depsRaw, ok := fields["deps"]
231		if !ok {
232			return pullRequest{}, errors.New("missing deps array")
233		}
234		if first := bytes.TrimSpace(depsRaw); len(first) == 0 || first[0] != '[' {
235			return pullRequest{}, errors.New("deps must be an array")
236		}
237		var deps []int
238		if err := json.Unmarshal(depsRaw, &deps); err != nil {
239			return pullRequest{}, fmt.Errorf("deps must contain integers: %w", err)
240		}
241		if deps == nil {
242			deps = []int{}
243		}
244	
245		checksRaw, ok := fields["checks"]
246		if !ok {
247			return pullRequest{}, errors.New("missing checks status")
248		}
249		var checks string
250		if err := json.Unmarshal(checksRaw, &checks); err != nil {
251			return pullRequest{}, fmt.Errorf("checks must be a string: %w", err)
252		}
253	
254		return pullRequest{id: id, deps: deps, checks: checks}, nil
255	}
