257	func findCycle(byID map[int]pullRequest) (int, bool) {
258		state := make(map[int]uint8, len(byID))
259		ids := sortedIDs(byID)
260		var visit func(int) (int, bool)
261		visit = func(id int) (int, bool) {
262			switch state[id] {
263			case 1:
264				return id, true
265			case 2:
266				return 0, false
267			}
268			state[id] = 1
269			for _, dep := range byID[id].deps {
270				if cycleID, ok := visit(dep); ok {
271					return cycleID, true
272				}
273			}
274			state[id] = 2
275			return 0, false
276		}
277	
278		for _, id := range ids {
279			if cycleID, ok := visit(id); ok {
280				return cycleID, true
281			}
282		}
283		return 0, false
284	}
285	
286	func sortedIDs(byID map[int]pullRequest) []int {
287		ids := make([]int, 0, len(byID))
288		for id := range byID {
289			ids = append(ids, id)
290		}
291		sort.Ints(ids)
292		return ids
293	}
