10	func TestRunEmptyQueueUsesEmptyArrays(t *testing.T) {
11		var stdout, stderr bytes.Buffer
12		if code := run(strings.NewReader(`{"prs":[]}`), &stdout, &stderr); code != 0 {
13			t.Fatalf("run exit code = %d, stderr = %q", code, stderr.String())
14		}
15		if got, want := stdout.String(), "{\"waves\":[],\"blocked\":[]}\n"; got != want {
16			t.Fatalf("stdout = %q, want %q", got, want)
17		}
18	}
