20	func TestPlanDiamondAndInputOrder(t *testing.T) {
21		inputs := []string{
22			`{"prs":[{"id":4,"deps":[2,3],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"},{"id":1,"deps":[],"checks":"pass"},{"id":3,"deps":[1],"checks":"pass"}]}`,
23			`{"prs":[{"id":1,"deps":[],"checks":"pass"},{"id":3,"deps":[1],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"},{"id":4,"deps":[2,3],"checks":"pass"}]}`,
24		}
25		want := `{"waves":[[1],[2,3],[4]],"blocked":[]}`
26		for _, input := range inputs {
27			var stdout, stderr bytes.Buffer
28			if code := run(strings.NewReader(input), &stdout, &stderr); code != 0 {
29				t.Fatalf("run exit code = %d, stderr = %q", code, stderr.String())
30			}
31			if got := strings.TrimSpace(stdout.String()); got != want {
32				t.Errorf("stdout = %s, want %s", got, want)
33			}
34		}
35	}
