95	func TestInvalidInputExitsTwoWithDiagnosticAndNoOutput(t *testing.T) {
96		tests := []struct {
97			name  string
98			input string
99		}{
100			{"duplicate IDs", `{"prs":[{"id":1,"deps":[],"checks":"pass"},{"id":1,"deps":[],"checks":"pass"}]}`},
101			{"missing dependency", `{"prs":[{"id":1,"deps":[2],"checks":"pass"}]}`},
102			{"cycle", `{"prs":[{"id":1,"deps":[2],"checks":"pass"},{"id":2,"deps":[1],"checks":"pass"}]}`},
103			{"cycle through failed PR", `{"prs":[{"id":1,"deps":[2],"checks":"fail"},{"id":2,"deps":[1],"checks":"pending"}]}`},
104			{"zero ID", `{"prs":[{"id":0,"deps":[],"checks":"pass"}]}`},
105			{"negative ID", `{"prs":[{"id":-1,"deps":[],"checks":"pass"}]}`},
106			{"bad status", `{"prs":[{"id":1,"deps":[],"checks":"unknown"}]}`},
107			{"malformed JSON", `{"prs":`},
108			{"trailing JSON", `{"prs":[]} {"prs":[]}`},
