126	func TestPlanOutputIsJSON(t *testing.T) {
127		result, err := plan(strings.NewReader(`{"prs":[{"id":2,"deps":[],"checks":"pending"}]}`))
128		if err != nil {
129			t.Fatal(err)
130		}
131		data, err := json.Marshal(result)
132		if err != nil {
133			t.Fatal(err)
